const URL = "https://pokeapi.co/api/v2/pokemon/";

// Fetches API data for pokemon not hard-coded
export default async function fetchApiData(startNum) {
  const checkNum = 1500;
  const apiPokemon = [];

  for (let i = startNum; i < checkNum; i++) {
    const response = await fetch(URL + i);
    if (response.status === 404) break; // breaks loop when there are no more pokemon
    const data = await response.json();
    // storing specific data makes it easier to work with and hard-code
    const individualData = {
      num: data.id,
      name: data.name,
      sprite1: data.sprites.front_default,
      sprite2: data.sprites.other.showdown.front_default
        ? data.sprites.other.showdown.front_default
        : data.sprites.other["official-artwork"].front_default,
      height: data.height,
      weight: data.weight,
      ability1: data.abilities[0].ability.name,
      ability2: data.abilities.hasOwnProperty(1)
        ? data.abilities[1].ability.name
        : "",
      ability3: data.abilities.hasOwnProperty(2)
        ? data.abilities[2].ability.name
        : "",
      type1: data.types[0].type.name,
      type2: data.types.hasOwnProperty(1) ? data.types[1].type.name : "none",
      hp: data.stats[0].base_stat,
      att: data.stats[1].base_stat,
      def: data.stats[2].base_stat,
      satt: data.stats[3].base_stat,
      sdef: data.stats[4].base_stat,
      spd: data.stats[5].base_stat,
    };
    apiPokemon.push(individualData);
  }

  return apiPokemon;
}
