import React, { useState, useEffect } from "react";
import SortMenu from "./SortMenu";
import TypeButtons from "./TypeButtons";
import { searchData } from "../scripts/dataHandler";

// All of the filter options: Search, Filter, Types
export default function FilterMenu(props) {
  const [searchText, setSearchText] = useState("");
  useEffect(() => {
    searchData(props.setShown, props.data, searchText);
  }, [searchText]);

  return (
    <div id="search" className="search">
      <div className="flexbox">
        <h4>Search:</h4>
        <input
          value={searchText}
          onChange={(e) => {
            setSearchText(e.target.value);
          }}
          id="searchBar"
          className="searchBar"
          type="text"
          placeholder="Type name here."
        />
        <SortMenu data={props.data} setShown={props.setShown} />
      </div>
      <TypeButtons data={props.data} setShown={props.setShown} />
    </div>
  );
}
