import currentPokemon from "../data/currentPokemon.js";
import fetchApiData from "./fetchApiData.js";

// Combines the hard-coded pokemon array and the api pokemon array
export async function gatherPokemonData() {
  const startNum = currentPokemon.length + 1;
  const apiPokemon = await fetchApiData(startNum);
  const allPokemon = [...currentPokemon, ...apiPokemon];
  return allPokemon;
}

// Searches allPokemon with the text typed into the search bar
export function searchData(setShownPokemon, allPokemon, searchText) {
  if (searchText === "") {
    setShownPokemon(allPokemon);
  }
  setShownPokemon(
    allPokemon
      .slice()
      .filter((pokemon) => pokemon.name.includes(searchText.toLowerCase()))
  );
}

// Sorts the pokemon by their type
export function typeFilter(props, typeInput) {
  props.setShown(
    props.data
      .slice()
      .filter(
        (pokemon) =>
          pokemon.type1.includes(typeInput.toLowerCase()) ||
          pokemon.type2.includes(typeInput.toLowerCase())
      )
  );
}

// Applies the selected sorting method from the drop down
export function sortData(setShownPokemon, allPokemon) {
  const dataCondition = document.getElementById("sort-menu").value;
  if (dataCondition === "a-z") {
    setShownPokemon(
      allPokemon.slice().sort((a, b) => a.name.localeCompare(b.name))
    );
  } else if (dataCondition === "z-a") {
    setShownPokemon(
      allPokemon.slice().sort((b, a) => a.name.localeCompare(b.name))
    );
  } else if (dataCondition === "heightShort") {
    setShownPokemon(allPokemon.slice().sort((a, b) => a.height - b.height));
  } else if (dataCondition === "heightTall") {
    setShownPokemon(allPokemon.slice().sort((b, a) => a.height - b.height));
  } else if (dataCondition === "weightLight") {
    setShownPokemon(allPokemon.slice().sort((a, b) => a.weight - b.weight));
  } else if (dataCondition === "weightHeavy") {
    setShownPokemon(allPokemon.slice().sort((b, a) => a.weight - b.weight));
  } else if (dataCondition === "type") {
    setShownPokemon(
      allPokemon.slice().sort((a, b) => a.type1.localeCompare(b.type1))
    );
  } else {
    setShownPokemon(allPokemon);
  }
}
