import React, { useEffect } from "react";
import { sortData } from "../scripts/dataHandler";

// Drop down menu to sort the array of pokemon
export default function SortMenu(props) {
  return (
    <select
      name=""
      defaultValue="none"
      id="sort-menu"
      className="sort-menu"
      onInput={() => {
        sortData(props.setShown, props.data);
      }}
    >
      <option value="none" hidden>
        Filter
      </option>
      <option value="number">Number</option>
      <option value="a-z">Alphabetical (A-Z)</option>
      <option value="z-a">Alphabetical (Z-A)</option>
      <option value="heightShort">Height (Shortest to Tallest)</option>
      <option value="heightTall">Height (Tallest to Shortest)</option>
      <option value="weightLight">Weight (Lightest to Heaviest)</option>
      <option value="weightHeavy">Weight (Heaviest to Lightest)</option>
      <option value="type">Type (Bug - Water)</option>
    </select>
  );
}
